-- karateka.lt test svetainės DB atnaujinimas iki v1.7 (db/008 - db/999 vienu failu).
-- phpMyAdmin -> aus15792_test -> Import. Galima importuoti ir kelis kartus: kas jau yra, praleidžiama.
-- Esami duomenys (naujienos, renginiai, nariai) nekeičiami - tik pridedamos lentelės ir stulpeliai.
SET NAMES utf8mb4;

-- ===== 008_belts_tasks_visibility.sql =====
-- Diržai, pamokos pagal diržą, užduotys pastabose, renginiai / naujienos tik nariams
SET NAMES utf8mb4;

-- Diržas: 1 = 9 kyu (baltas) ... 9 = 1 kyu (rudas), 10 = 1 dan ... 18 = 9 dan. NULL - nenurodytas.
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'members' AND COLUMN_NAME = 'belt_level') = 0, 'ALTER TABLE members ADD COLUMN belt_level TINYINT UNSIGNED NULL AFTER group_id', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- Pamokos diržui (NULL - visiems)
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'lessons' AND COLUMN_NAME = 'belt_level') = 0, 'ALTER TABLE lessons ADD COLUMN belt_level TINYINT UNSIGNED NULL AFTER topic', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- Pastaba gali būti užduotis (vaikas pažymi "Atlikta") ir turėti prisegtą pamoką
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'coach_notes' AND COLUMN_NAME = 'lesson_id') = 0, 'ALTER TABLE coach_notes ADD COLUMN lesson_id INT UNSIGNED NULL AFTER youtube_id', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'coach_notes' AND COLUMN_NAME = 'is_task') = 0, 'ALTER TABLE coach_notes ADD COLUMN is_task TINYINT(1) NOT NULL DEFAULT 0 AFTER lesson_id', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'coach_notes' AND COLUMN_NAME = 'done_at') = 0, 'ALTER TABLE coach_notes ADD COLUMN done_at DATETIME NULL AFTER read_at', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = 'coach_notes' AND CONSTRAINT_NAME = 'fk_cn_lesson') = 0, 'ALTER TABLE coach_notes ADD CONSTRAINT fk_cn_lesson FOREIGN KEY (lesson_id) REFERENCES lessons(id) ON DELETE SET NULL', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- Matomumas: 1 - tik prisijungusiems nariams
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'events' AND COLUMN_NAME = 'members_only') = 0, 'ALTER TABLE events ADD COLUMN members_only TINYINT(1) NOT NULL DEFAULT 0 AFTER is_abroad', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'news' AND COLUMN_NAME = 'members_only') = 0, 'ALTER TABLE news ADD COLUMN members_only TINYINT(1) NOT NULL DEFAULT 0 AFTER is_published', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- ===== 009_attendance.sql =====
-- Lankomumas: kas buvo / nebuvo treniruotėje (žymima trenerio puslapyje "Treniruotė")
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS attendance (
  member_id      INT UNSIGNED NOT NULL,
  training_date  DATE NOT NULL,
  group_id       INT UNSIGNED NULL,
  present        TINYINT(1) NOT NULL,          -- 1 buvo, 0 nebuvo
  marked_by      INT UNSIGNED NULL,
  marked_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (member_id, training_date),
  KEY idx_att_group_date (group_id, training_date),
  CONSTRAINT fk_att_member FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE,
  CONSTRAINT fk_att_group  FOREIGN KEY (group_id)  REFERENCES training_groups(id) ON DELETE SET NULL,
  CONSTRAINT fk_att_by     FOREIGN KEY (marked_by) REFERENCES accounts(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ===== 010_attendance_points_note_source.sql =====
-- Taškai už lankomumą (skiriami automatiškai pažymėjus "Buvo") ir iš kur atėjo trenerio pastaba
SET NAMES utf8mb4;

-- Vertę ar išjungimą keičia administratorius: Treneriams -> Taškai

-- Pastaba palikta po treniruotės (grupė) arba po renginio (renginys); senos pastabos - be šaltinio
