PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'coach_notes' AND COLUMN_NAME = 'event_id') = 0, 'ALTER TABLE coach_notes ADD COLUMN event_id INT UNSIGNED NULL AFTER group_id', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = 'coach_notes' AND CONSTRAINT_NAME = 'fk_cn_group') = 0, 'ALTER TABLE coach_notes ADD CONSTRAINT fk_cn_group FOREIGN KEY (group_id) REFERENCES training_groups(id) ON DELETE SET NULL', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = 'coach_notes' AND CONSTRAINT_NAME = 'fk_cn_event') = 0, 'ALTER TABLE coach_notes ADD CONSTRAINT fk_cn_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- ===== 011_site_settings.sql =====
-- 011: svetainės nustatymai, kuriuos keičia adminas.
-- Pirmas nustatymas: kuriuos emoji nariai gali naudoti reakcijoms (Treneriams -> Naujienos 🙂).
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS site_settings (
  name        VARCHAR(60) NOT NULL PRIMARY KEY,
  value       TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

