-- ===== 012_varzybos.sql =====
-- Ryšys su varžybų sistema (varzybos.karateka.lt / ltkf.lt)
SET NAMES utf8mb4;

-- Lytis reikalinga varžybų kategorijoms (vaikinai / merginos). NULL - dar nenurodyta.
