-- ===== 013_dalyviai_zymos.sql =====
-- 013: renginių dalyviai (registracija, kvietimai) ir narių žymos (teisėjas, egzaminatorius)
SET NAMES utf8mb4;

-- Ar nariai gali registruotis patys ir iki kada (NULL - iki renginio pradžios)
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'events' AND COLUMN_NAME = 'registration') = 0, 'ALTER TABLE events ADD COLUMN registration TINYINT(1) NOT NULL DEFAULT 1 AFTER members_only', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'events' AND COLUMN_NAME = 'registration_until') = 0, 'ALTER TABLE events ADD COLUMN registration_until DATE NULL AFTER registration', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- Dalyviai: pakviesti, dalyvaus, negalės. role = 'referee' - registruojasi kaip teisėjas
CREATE TABLE IF NOT EXISTS event_participants (
  event_id      INT UNSIGNED NOT NULL,
  member_id     INT UNSIGNED NOT NULL,
  status        ENUM('invited','going','declined') NOT NULL,
  role          ENUM('participant','referee') NOT NULL DEFAULT 'participant',
  invited_by    INT UNSIGNED NULL,
  responded_at  DATETIME NULL,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (event_id, member_id),
  KEY idx_ep_member (member_id, status),
  CONSTRAINT fk_ep_event  FOREIGN KEY (event_id)   REFERENCES events(id)   ON DELETE CASCADE,
  CONSTRAINT fk_ep_member FOREIGN KEY (member_id)  REFERENCES members(id)  ON DELETE CASCADE,
  CONSTRAINT fk_ep_by     FOREIGN KEY (invited_by) REFERENCES accounts(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Žymos nustato, kokią papildomą medžiagą ir testus žmogus mato. „Karateka“ turi visi, todėl nesaugoma.
CREATE TABLE IF NOT EXISTS member_tags (
  member_id   INT UNSIGNED NOT NULL,
  tag         ENUM('teisejas','egzaminatorius') NOT NULL,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (member_id, tag),
  CONSTRAINT fk_mt_member FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ===== 014_egzaminai_testai.sql =====
-- 014: egzamino programa pagal diržą, testai (kaip Regitroje), pamokos teisėjams ir egzaminatoriams
SET NAMES utf8mb4;

-- Ko reikia norint gauti diržą (belt_level - diržas, kurį gausi išlaikęs)
CREATE TABLE IF NOT EXISTS belt_requirements (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  belt_level  TINYINT UNSIGNED NOT NULL,
  section     ENUM('kihon','kata','kumite','teorija','kita') NOT NULL DEFAULT 'kita',
  title       VARCHAR(190) NOT NULL,
  body        TEXT NULL,
  youtube_id  VARCHAR(20) NULL,
  lesson_id   INT UNSIGNED NULL,
  sort_order  INT NOT NULL DEFAULT 0,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_br_belt (belt_level, section, sort_order),
  CONSTRAINT fk_br_lesson FOREIGN KEY (lesson_id) REFERENCES lessons(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Kuriuos programos punktus narys jau moka (žvaigždutės ir pasiruošimo juosta)
CREATE TABLE IF NOT EXISTS requirement_progress (
  member_id       INT UNSIGNED NOT NULL,
  requirement_id  INT UNSIGNED NOT NULL,
  done_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (member_id, requirement_id),
  CONSTRAINT fk_rp_member FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE,
  CONSTRAINT fk_rp_req    FOREIGN KEY (requirement_id) REFERENCES belt_requirements(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Testai. audience: kas mato (karateka - visi nariai, kiti - pagal žymą). belt_level: kuriam diržui (NULL - visiems)
CREATE TABLE IF NOT EXISTS quizzes (
  id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  title           VARCHAR(190) NOT NULL,
  audience        ENUM('karateka','teisejas','egzaminatorius') NOT NULL DEFAULT 'karateka',
  belt_level      TINYINT UNSIGNED NULL,
  description     TEXT NULL,
  question_count  TINYINT UNSIGNED NOT NULL DEFAULT 10,
  pass_percent    TINYINT UNSIGNED NOT NULL DEFAULT 83,
  kids_mode       TINYINT(1) NOT NULL DEFAULT 0,
  is_published    TINYINT(1) NOT NULL DEFAULT 1,
  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      DATETIME NULL,
  KEY idx_quiz_aud (audience, belt_level)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS quiz_questions (
  id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  quiz_id      INT UNSIGNED NOT NULL,
  body         TEXT NOT NULL,
  image        VARCHAR(80) NULL,
  youtube_id   VARCHAR(20) NULL,
  explanation  TEXT NULL,
  sort_order   INT NOT NULL DEFAULT 0,
  KEY idx_qq_quiz (quiz_id),
  CONSTRAINT fk_qq_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS quiz_answers (
  id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  question_id  INT UNSIGNED NOT NULL,
  body         VARCHAR(255) NOT NULL,
  is_correct   TINYINT(1) NOT NULL DEFAULT 0,
  sort_order   INT NOT NULL DEFAULT 0,
  KEY idx_qa_q (question_id),
  CONSTRAINT fk_qa_q FOREIGN KEY (question_id) REFERENCES quiz_questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Bandymai: tik „tikras“ testas (treniruotės režimas nesaugomas)
CREATE TABLE IF NOT EXISTS quiz_attempts (
  id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  quiz_id       INT UNSIGNED NOT NULL,
  member_id     INT UNSIGNED NOT NULL,
  account_id    INT UNSIGNED NULL,
  question_ids  TEXT NOT NULL,
  score         SMALLINT UNSIGNED NULL,
  total         SMALLINT UNSIGNED NOT NULL,
  passed        TINYINT(1) NULL,
  started_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  finished_at   DATETIME NULL,
  KEY idx_att_member (member_id, quiz_id),
  CONSTRAINT fk_qat_quiz    FOREIGN KEY (quiz_id)    REFERENCES quizzes(id)  ON DELETE CASCADE,
  CONSTRAINT fk_qat_member  FOREIGN KEY (member_id)  REFERENCES members(id)  ON DELETE CASCADE,
  CONSTRAINT fk_qat_account FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS quiz_attempt_answers (
  attempt_id   INT UNSIGNED NOT NULL,
  question_id  INT UNSIGNED NOT NULL,
  answer_id    INT UNSIGNED NULL,
  is_correct   TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (attempt_id, question_id),
  CONSTRAINT fk_qaa_attempt FOREIGN KEY (attempt_id) REFERENCES quiz_attempts(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Pamokos teisėjams ir egzaminatoriams (mato tik turintys žymą)
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'lessons' AND COLUMN_NAME = 'audience') = 0, 'ALTER TABLE lessons ADD COLUMN audience ENUM(''karateka'',''teisejas'',''egzaminatorius'') NOT NULL DEFAULT ''karateka'' AFTER belt_level', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- ===== 015_sms.sql =====
-- 015: SMS žinutės (siunčia tik adminas) ir jų istorija
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS sms_messages (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  body        TEXT NOT NULL,
  parts       TINYINT UNSIGNED NOT NULL DEFAULT 1,       -- iš kiek SMS dalių sudaryta viena žinutė
  provider    VARCHAR(20) NOT NULL,                      -- log (bandomasis režimas) | twilio
  sent_count  INT UNSIGNED NOT NULL DEFAULT 0,
  failed_count INT UNSIGNED NOT NULL DEFAULT 0,
  cost_eur    DECIMAL(8,3) NULL,                         -- apytikslė kaina pagal config sms.price_eur
  label       VARCHAR(190) NULL,                         -- kam siųsta, pvz. „Grupės: Jaunimas“
  sent_by     INT UNSIGNED NULL,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_sms_created (created_at),
  CONSTRAINT fk_sms_by FOREIGN KEY (sent_by) REFERENCES accounts(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sms_recipients (
  id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  message_id   INT UNSIGNED NOT NULL,
  account_id   INT UNSIGNED NULL,
  name         VARCHAR(190) NOT NULL,
  phone        VARCHAR(40) NOT NULL,
  for_members  VARCHAR(255) NULL,                        -- dėl kurių narių (pvz. tėvams - vaikų vardai)
  status       ENUM('sent','failed','test') NOT NULL,
  provider_id  VARCHAR(64) NULL,
  error        VARCHAR(255) NULL,
  KEY idx_smsr_msg (message_id),
  CONSTRAINT fk_smsr_msg FOREIGN KEY (message_id) REFERENCES sms_messages(id) ON DELETE CASCADE,
  CONSTRAINT fk_smsr_acc FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ===== 016_pamoku_aplankai.sql =====
-- 016: pamokų aplankai (aplankai aplankuose), pamokos turinys blokais (tekstas, video, nuotrauka, pastaba...), tvarka
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS lesson_folders (
  id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  parent_id     INT UNSIGNED NULL,                  -- NULL - pagrindinis lygis
  title         VARCHAR(120) NOT NULL,
  icon          VARCHAR(16) NULL,                   -- emoji, pvz. 🥋
  description   TEXT NULL,
  audience      ENUM('karateka','teisejas','egzaminatorius') NOT NULL DEFAULT 'karateka',
  is_published  TINYINT(1) NOT NULL DEFAULT 1,
  sort_order    INT NOT NULL DEFAULT 0,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_lf_parent (parent_id, sort_order),
  CONSTRAINT fk_lf_parent FOREIGN KEY (parent_id) REFERENCES lesson_folders(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'lessons' AND COLUMN_NAME = 'folder_id') = 0, 'ALTER TABLE lessons ADD COLUMN folder_id INT UNSIGNED NULL AFTER id', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'lessons' AND COLUMN_NAME = 'sort_order') = 0, 'ALTER TABLE lessons ADD COLUMN sort_order INT NOT NULL DEFAULT 0 AFTER folder_id', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = 'lessons' AND CONSTRAINT_NAME = 'fk_lessons_folder') = 0, 'ALTER TABLE lessons ADD CONSTRAINT fk_lessons_folder FOREIGN KEY (folder_id) REFERENCES lesson_folders(id) ON DELETE SET NULL', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- Pamokos turinys: blokai vienas po kito. Senos pamokos be blokų rodomos kaip anksčiau (tekstas + video).
CREATE TABLE IF NOT EXISTS lesson_blocks (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  lesson_id   INT UNSIGNED NOT NULL,
  type        ENUM('heading','text','video','image','note','link') NOT NULL,
  body        TEXT NULL,             -- tekstas, pastaba, antraštė arba nuorodos tekstas
  youtube_id  VARCHAR(20) NULL,
  image       VARCHAR(100) NULL,     -- failas uploads/lessons/
  url         VARCHAR(500) NULL,
  caption     VARCHAR(255) NULL,     -- prierašas po video ar nuotrauka
  sort_order  INT NOT NULL DEFAULT 0,
  KEY idx_lb_lesson (lesson_id, sort_order),
  CONSTRAINT fk_lb_lesson FOREIGN KEY (lesson_id) REFERENCES lessons(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Esamos pamokų temos tampa aplankais (pamokos nesikeičia, tik atsiduria savo temos aplanke)
-- (tik pirmą kartą: kol aplankų dar nėra ir pamokos dar nesurikiuotos)
SET @do_folders = ((SELECT COUNT(*) FROM lesson_folders) = 0 AND (SELECT COUNT(*) FROM lessons WHERE sort_order <> 0) = 0);
UPDATE lesson_folders SET sort_order = id WHERE @do_folders = 1;
UPDATE lessons l JOIN lesson_folders f ON f.title = l.topic AND f.parent_id IS NULL SET l.folder_id = f.id WHERE @do_folders = 1;
UPDATE lessons SET sort_order = id WHERE @do_folders = 1;

-- ===== 017_renginiai_pakviestiems.sql =====
-- 017: renginys tik pakviestiems (kai „Kam skirta?“ pažymėti tik konkretūs žmonės, o ne visa grupė)
SET NAMES utf8mb4;

SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'events' AND COLUMN_NAME = 'invited_only') = 0, 'ALTER TABLE events ADD COLUMN invited_only TINYINT(1) NOT NULL DEFAULT 0 AFTER registration_until', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- ===== 018_zinutes.sql =====
-- 018: nario ir trenerio žinutės: atsakymai į trenerio pastabas, klausimai prie pamokų, bendros žinutės.
-- Nario žinutes mato tik treneriai, trenerio atsakymus - tik tas narys (ir jo tėvai).
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS member_messages (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  member_id   INT UNSIGNED NOT NULL,              -- kurio nario pokalbis
  note_id     INT UNSIGNED NULL,                  -- atsakymas į trenerio pastabą
  lesson_id   INT UNSIGNED NULL,                  -- klausimas ar komentaras prie pamokos
  author_id   INT UNSIGNED NULL,                  -- kas parašė (paskyra)
  from_staff  TINYINT(1) NOT NULL DEFAULT 0,      -- 1 - treneris, 0 - narys ar tėvai
  body        TEXT NOT NULL,
  read_at     DATETIME NULL,                      -- kada perskaitė kita pusė
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_mm_member (member_id, created_at),
  KEY idx_mm_unread (from_staff, read_at),
  CONSTRAINT fk_mm_member FOREIGN KEY (member_id) REFERENCES members(id)      ON DELETE CASCADE,
  CONSTRAINT fk_mm_note   FOREIGN KEY (note_id)   REFERENCES coach_notes(id)  ON DELETE CASCADE,
  CONSTRAINT fk_mm_lesson FOREIGN KEY (lesson_id) REFERENCES lessons(id)      ON DELETE SET NULL,
  CONSTRAINT fk_mm_author FOREIGN KEY (author_id) REFERENCES accounts(id)     ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ===== 019_wtku_teiseju_testas.sql =====
-- 019: WTKU teisėjų testas (300 klausimų iš WTKU Traditional Karate Competition Rules)
-- ir du nauji testų nustatymai: laiko limitas ir to paties klausimo formuluotės (tema).
-- Failą galima importuoti ir antrą kartą: kas jau yra - praleidžiama.
SET NAMES utf8mb4;

-- Laiko limitas minutėmis (0 - neribota). Pradedant testą įrašoma, iki kada jį reikia baigti.
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'quizzes' AND COLUMN_NAME = 'time_limit') = 0, 'ALTER TABLE quizzes ADD COLUMN IF NOT EXISTS time_limit SMALLINT UNSIGNED NOT NULL DEFAULT 0 AFTER pass_percent', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'quiz_attempts' AND COLUMN_NAME = 'deadline_at') = 0, 'ALTER TABLE quiz_attempts ADD COLUMN IF NOT EXISTS deadline_at DATETIME NULL AFTER started_at', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- Tema: to paties klausimo kitos formuluotės. Viename teste iš temos būna tik vienas klausimas.
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'quiz_questions' AND COLUMN_NAME = 'topic') = 0, 'ALTER TABLE quiz_questions ADD COLUMN IF NOT EXISTS topic VARCHAR(190) NULL AFTER quiz_id', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- Testas teisėjams: 50 klausimų iš 100 temų, reikia 80 %, 60 min. (keičiama: Treneriams -> Testai)
-- Įkeliama tik jei tokio testo dar nėra.
SET @do_wtku = (SELECT COUNT(*) FROM quizzes WHERE title = 'WTKU teisėjų testas') = 0;
SET @wtku = (SELECT id FROM quizzes WHERE title = 'WTKU teisėjų testas' ORDER BY id LIMIT 1);

-- Klausimai (paaiškinimas - vieta taisyklėse) ir atsakymai (pirmas - teisingas; teste tvarka sumaišoma)

-- ===== 020_nuotrauku_sutikimai.sql =====
-- 020: nuotraukų sutikimai pagal tai, KAS skelbia (ne kur nufotografuota).
--   members.photo_consent - klubas: karateka.lt ir klubo socialiniai tinklai (kaip iki šiol)
--   members.photo_events  - varžybų organizatorius: varžybų nuotraukos ir video (NULL - tėvai dar neatsakė)
-- Kiekvienas atsakymas įrašomas į consent_log: kas, kada ir ką atsakė.
-- Failą galima importuoti ir antrą kartą: kas jau yra - praleidžiama.
SET NAMES utf8mb4;

SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'members' AND COLUMN_NAME = 'photo_events') = 0, 'ALTER TABLE members ADD COLUMN IF NOT EXISTS photo_events TINYINT(1) NULL AFTER photo_consent', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'members' AND COLUMN_NAME = 'photo_answered_at') = 0, 'ALTER TABLE members ADD COLUMN IF NOT EXISTS photo_answered_at DATETIME NULL AFTER photo_events', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'members' AND COLUMN_NAME = 'photo_answered_by') = 0, 'ALTER TABLE members ADD COLUMN IF NOT EXISTS photo_answered_by INT UNSIGNED NULL AFTER photo_answered_at', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

CREATE TABLE IF NOT EXISTS consent_log (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  member_id   INT UNSIGNED NOT NULL,
  kind        VARCHAR(30) NOT NULL,          -- photo_club | photo_events
  value       TINYINT(1) NOT NULL,
  account_id  INT UNSIGNED NULL,             -- kas atsakė (tėvai, pats narys ar treneris)
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY k_member (member_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
